window.__votdWeek && window.__votdWeek({"week":"2029-11-12","reading":"Doctrine and Covenants 129–132","days":[{"d":"2029-11-12","ref":"D&C 129:8","b":"D&C","c":129,"v":8,"he":"וְאִם הַשָּׂטָן הוּא כְּמַלְאַךְ אוֹר וּבִקַּשְׁתָּ מִמֶּנּוּ לִלְחֹץ יָדְךָ יוֹשִׁיט יָדוֹ וְלֹא תִמְצָא מְאוּמָה וּבָזֶה תַּכִּירֶנּוּ׃","en":"If it be the devil as an angel of light, when you ask him to shake hands he will offer you his hand, and you will not feel anything; you may therefore detect him."},{"d":"2029-11-13","ref":"D&C 130:7","b":"D&C","c":130,"v":7,"he":"כִּי יוֹשְׁבִים הֵם לִפְנֵי הָאֱלֹהִים עַל גַּלְגַּל כְּיָם זְכוּכִית וָאֵשׁ אֲשֶׁר שָׁם נִגְלֶה לָהֶם כֹּל לִכְבוֹדָם עָבָר וְהֹוֶה וְעָתִיד וְהֵם תָּמִיד לִפְנֵי יְהוָה׃","en":"But they reside in the presence of God, on a globe like a sea of glass and fire, where all things for their glory are manifest, past, present, and future, and are continually before the Lord."},{"d":"2029-11-14","ref":"D&C 130:22","b":"D&C","c":130,"v":22,"he":"לָאָב גּוּף בָּשָׂר וַעֲצָמוֹת כְּגוּף הָאָדָם וְכֵן לַבֵּן אַךְ רוּחַ־הַקֹּדֶשׁ אֵין־לוֹ גּוּף בָּשָׂר וַעֲצָמוֹת כִּי רוּחַ הוּא וְאִלּוּלֵי כֵן לֹא יָכֹל לִשְׁכֹּן בָּנוּ׃","en":"The Father has a body of flesh and bones as tangible as man's; the Son also; but the Holy Ghost has not a body of flesh and bones, but is a personage of Spirit. Were it not so, the Holy Ghost could not dwell in us."},{"d":"2029-11-15","ref":"D&C 131:3","b":"D&C","c":131,"v":3,"he":"וְאִם לֹא יָבוֹא לֹא יַשִּׂיג אוֹתָהּ׃","en":"And if he does not, he cannot obtain it."},{"d":"2029-11-16","ref":"D&C 131:4","b":"D&C","c":131,"v":4,"he":"יָכוֹל לָבוֹא אֶל־הָאַחֶרֶת אַךְ שָׁם קֵץ מַלְכוּתוֹ וְלֹא יִרְבֶּה׃","en":"He may enter into the other, but that is the end of his kingdom; he cannot have an increase."},{"d":"2029-11-17","ref":"D&C 132:22","b":"D&C","c":132,"v":22,"he":"כִּי צַר הַפֶּתַח וּמוּצָק הַדֶּרֶךְ הַמּוֹבִיל אֶל הַהִתְנַשְּׂאוּת וּמֶשֶׁךְ הַחַיִּים וּמְעַטִּים הֵם אֲשֶׁר יִמְצְאוּהָ כִּי אֵינְכֶם מְקַבְּלִים אוֹתִי בָּעוֹלָם וְאֵינְכֶם יוֹדְעִים אוֹתִי׃","en":"For strait is the gate, and narrow the way that leadeth unto the exaltation and continuation of the lives, and few there be that find it, because ye receive me not in the world neither do ye know me."},{"d":"2029-11-18","ref":"D&C 132:25","b":"D&C","c":132,"v":25,"he":"רָחָב הַפֶּתַח וּמְרֻוַּחַת הַדֶּרֶךְ הַמּוֹבִיל אֶל־הַמּוֹתִים וְרַבִּים הַהֹלְכִים בָּהּ כִּי אֵינָם מְקַבְּלִים אוֹתִי וְאֵינָם עֹמְדִים בְּחֻקִּי׃","en":"Broad is the gate, and wide the way that leadeth to the deaths; and many there are that go in thereat, because they receive me not, neither do they abide in my law."}]});
